<template>
  <div class="schedule-home">
    <ScheduleHeader :termInformation="termInformation" />
    <div class="preview">
      <div class="item">
        <span>周：</span>
        <el-input v-model="customOverallWeek" style="width: 100px">
          <template #append><el-button :icon="Search" @click="changeOverallWeek" /></template>
        </el-input>
      </div>
      <div class="item">
        <el-button @click="onRestore">恢复默认</el-button>
      </div>
    </div>
    <br />
    <ScheduleTable :termInformation="termInformation" />
  </div>
</template>

<script lang="ts" setup>
import { ref, Ref, onBeforeUnmount, nextTick } from "vue";
import dayjs from "dayjs";
import { Search } from '@element-plus/icons-vue'
import ScheduleHeader from "./schedule-header.vue";
import ScheduleTable from "./scheduleTable/table-index.vue";
import { ITermInformation } from "@/types/schedule";

const termInformation: Ref<ITermInformation> = ref({
  beginDate: dayjs("2025-02-17"),
  curDate: dayjs(),
  overallWeek: 0,
  isOddWeek: true,
});
const timeLoop = () => {
  const { beginDate, curDate } = termInformation.value;
  termInformation.value.curDate = curDate.add(1, "second");
  const diffWeek = curDate.diff(beginDate, "week") + 1;
  termInformation.value.overallWeek = diffWeek;
  termInformation.value.isOddWeek = Boolean(diffWeek % 2);
}
timeLoop();
const customOverallWeek = ref(termInformation.value.overallWeek);
const timer = setInterval(() => {
  timeLoop();
}, 1000);


const changeOverallWeek = () => {
  const { beginDate } = termInformation.value;
  const setDate = dayjs(beginDate).add(customOverallWeek.value - 1, 'week');
  termInformation.value.curDate = setDate;
}
const onRestore = () => {
  termInformation.value.curDate = dayjs();
}

onBeforeUnmount(() => {
  clearInterval(timer);
});
</script>

<style lang="less" scoped>
.preview {
  display: flex;
  padding: 0 1rem;

  .item+.item {
    margin-left: 1rem;
  }
}
</style>
